/bin/bash -lc "python - <<'PY'
import pathlib,re
for f in sorted(pathlib.Path('/docs').glob('*.txt')):
 s=f.read_text(); page='?'; hits=[]
 for l in s.splitlines():
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'new york|laws? of|construed|govern',l,re.I): hits.append((page,l.strip()))
 print('\\nFILE:',f.name[:-4])
 for p,l in hits: print('p.',p,l)
PY"

